import json, urllib.request, urllib.error
base='http://host.docker.internal:8072'
key=json.load(open('/run/secrets/model.json'))['api_key']

def call(method,path,body=None):
    req=urllib.request.Request(base+path, data=json.dumps(body).encode() if body is not None else None,
        headers={'Authorization':'***'+key,'Content-Type':'application/json'}, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.read().decode()[:600]
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode(errors='replace')[:300]
    except Exception as e:
        return 'ERR', str(e)

print(call('GET','/v1/models'))
for p in ['/v1/images/generations','/images/generations','/v1/image/generations','/v1/images','/v1/images/generate']:
    print(p, call('POST', p, {'model':'ecnu-image','prompt':'test','size':'512x512'}))
