* {margin:0;padding:0;box-sizing:border-box}
html,body{width:3840px;height:2160px;overflow:hidden}
body{background:#FAFBFD;font-family:'Noto Sans CJK SC','Noto Sans CJK','WenQuanYi Zen Hei',sans-serif;color:#0F2E5C;}
.page{width:3840px;height:2160px;position:relative;padding:110px 140px;display:flex;flex-direction:column;}
.kicker{font-size:38px;color:#4A6BA8;letter-spacing:8px;margin-bottom:24px;font-weight:500;}
.t{font-size:88px;font-weight:700;line-height:1.28;letter-spacing:2px;}
.t2{font-size:60px;font-weight:600;line-height:1.4;color:#2A4C86;}
.bar{width:250px;height:12px;border-radius:6px;background:linear-gradient(90deg,#1E5EFF,#00B8D9);margin-top:36px;}
.sub{font-size:46px;color:#54719F;margin-top:34px;line-height:1.55;font-weight:400;}
.grad{background:linear-gradient(92deg,#1E5EFF 10%,#00B8D9 90%);-webkit-background-clip:text;background-clip:text;color:transparent;}
.gradbg{background:linear-gradient(92deg,#1E5EFF,#00B8D9);color:#fff;}
.card{background:#FFFFFF;border:3px solid #DFE8F6;border-radius:30px;box-shadow:0 14px 40px rgba(30,94,255,.07);}
.chip{display:inline-flex;align-items:center;justify-content:center;padding:18px 42px;border-radius:60px;border:3px solid #C9DCF8;background:#F2F7FF;color:#1D4E9E;font-size:42px;font-weight:500;white-space:nowrap;}
.chip.hl{background:linear-gradient(92deg,#1E5EFF,#00B8D9);border-color:transparent;color:#fff;font-weight:600;}
.ic{display:flex;align-items:center;justify-content:center;border-radius:50%;background:#EAF2FE;color:#1E5EFF;}
.ic.cy{background:#E4F7FB;color:#0891B2;}
.note{font-size:38px;color:#7288AC;line-height:1.5;}
.big-line{font-size:66px;font-weight:600;line-height:1.45;}
.dim{color:#33517F;}
.abs{position:absolute;}
.row{display:flex;align-items:center;}
.col{display:flex;flex-direction:column;}
.grow{flex:1}
svg text{font-family:'Noto Sans CJK SC','Noto Sans CJK',sans-serif;}
