def icon(name, size=64, color=None, cls=''):
    c = color or 'currentColor'
    return ('<span class="ic %s" style="width:%dpx;height:%dpx;flex:none;">'
            '<svg width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="%s" '
            'stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">%s</svg></span>'
            % (cls, size, size, size*0.62, size*0.62, c, ICONS[name]))

def icon_plain(name, size=64, color=None, sw=1.6):
    c = color or BLUE
    return ('<svg width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="%s" '
            'stroke-width="%s" stroke-linecap="round" stroke-linejoin="round">%s</svg>'
            % (size, size, c, sw, ICONS[name]))

def arrow_right(w=120, h=28, color=BLUE, op=1.0):
    return ('<svg width="%d" height="%d" viewBox="0 0 120 28" fill="none" opacity="%s">'
            '<path d="M2 14h100" stroke="%s" stroke-width="5" stroke-linecap="round"/>'
            '<path d="M96 5l16 9-16 9" stroke="%s" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>'
